})

hl.layer_rule({
    name = "cc-blur",
    match = { namespace = "^(control-center)$" },
    blur = false,
})

hl.layer_rule({
    name = "settings-anim",
    match = { namespace = "^(settings)$" },
    animation = "slide top",
})

hl.layer_rule({
    name = "settings-blur",
    match = { namespace = "^(settings)$" },
